#!/usr/bin/env python3
"""
score.py — validate codings, compute scores, and measure inter-rater reliability.

This script enforces the methodology rather than trusting the coder:

  * every non-zero score must carry a quote and a source_id (METHODOLOGY 4.1)
  * every score must match an anchor that exists in rubric.csv for that dimension
  * hedged language caps an item at half marks, rounded down
  * dimensions with Cohen's kappa < 0.6 on the overlap sample are reported as UNRELIABLE
    and excluded from totals

Usage
-----
    python score.py --validate      # fail loudly on any protocol violation
    python score.py --reliability   # kappa per dimension on the double-coded sample
    python score.py --report        # per-dimension gaps, zero-counts, D10 headline
    python score.py                 # all three

Input: codings.csv with columns
    developer, dimension_id, coder, score, hedged, source_id, quote, note
One row per (developer, dimension, coder). Keep both coders' rows; never overwrite a
disagreement. Reconciled values are added as a third row with coder = "reconciled".
"""

from __future__ import annotations

import argparse
import csv
import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent
RUBRIC = ROOT / "rubric.csv"
CODINGS = ROOT / "codings.csv"
SOURCES = ROOT / "sources.csv"

KAPPA_FLOOR = 0.6
PRIMARY_CODER = "A"
CHECK_CODER = "B"
RECONCILED = "reconciled"


# --------------------------------------------------------------------------- loading


def load_rubric() -> tuple[dict[str, int], dict[tuple[str, int], str]]:
    if not RUBRIC.exists():
        sys.exit("rubric.csv not found")
    maxes: dict[str, int] = {}
    anchors: dict[tuple[str, int], str] = {}
    with RUBRIC.open(newline="", encoding="utf-8") as fh:
        for row in csv.DictReader(fh):
            did = row["dimension_id"].strip()
            maxes[did] = int(row["max_score"])
            anchors[(did, int(row["score"]))] = row["anchor"]
    return maxes, anchors


def load_codings() -> list[dict]:
    if not CODINGS.exists():
        print(
            "codings.csv not found.\n"
            "Expected header:\n"
            "  developer,dimension_id,coder,score,hedged,source_id,quote,note\n"
            "No data has been collected yet — this is the expected state before collection begins."
        )
        sys.exit(0)
    with CODINGS.open(newline="", encoding="utf-8") as fh:
        return [r for r in csv.DictReader(fh) if any((v or "").strip() for v in r.values())]


def known_source_ids() -> set[str]:
    if not SOURCES.exists():
        return set()
    with SOURCES.open(newline="", encoding="utf-8") as fh:
        return {r["source_id"] for r in csv.DictReader(fh)}


def truthy(v: str | None) -> bool:
    return (v or "").strip().lower() in {"1", "true", "yes", "y"}


# --------------------------------------------------------------------------- validation


def validate(codings: list[dict], maxes: dict[str, int], anchors: dict[tuple[str, int], str]) -> list[str]:
    problems: list[str] = []
    sids = known_source_ids()
    seen: set[tuple[str, str, str]] = set()

    for i, row in enumerate(codings, start=2):  # +2: header plus 1-indexing
        dev = (row.get("developer") or "").strip()
        did = (row.get("dimension_id") or "").strip()
        coder = (row.get("coder") or "").strip()
        where = f"row {i} [{dev}/{did}/{coder}]"

        if not dev or not did or not coder:
            problems.append(f"{where}: developer, dimension_id and coder are all required")
            continue
        if did not in maxes:
            problems.append(f"{where}: unknown dimension_id")
            continue

        key = (dev, did, coder)
        if key in seen:
            problems.append(f"{where}: duplicate coding — one row per developer/dimension/coder")
        seen.add(key)

        try:
            score = int((row.get("score") or "").strip())
        except ValueError:
            problems.append(f"{where}: score must be an integer")
            continue

        if not 0 <= score <= maxes[did]:
            problems.append(f"{where}: score {score} outside 0..{maxes[did]}")
            continue
        if (did, score) not in anchors:
            problems.append(f"{where}: no rubric anchor defined for score {score}")

        quote = (row.get("quote") or "").strip()
        sid = (row.get("source_id") or "").strip()
        if score > 0:
            if not quote:
                problems.append(f"{where}: non-zero score requires a quote (METHODOLOGY 4.1)")
            elif len(quote.split()) > 60:
                problems.append(f"{where}: quote is {len(quote.split())} words, limit is 60")
            if not sid:
                problems.append(f"{where}: non-zero score requires a source_id")
            elif sids and sid not in sids:
                problems.append(f"{where}: source_id '{sid}' is not registered in sources.csv")

        if truthy(row.get("hedged")):
            cap = maxes[did] // 2
            if score > cap:
                problems.append(
                    f"{where}: marked hedged, so score is capped at {cap} (got {score}) — "
                    "see METHODOLOGY 4.1"
                )
    return problems


# --------------------------------------------------------------------------- reliability


def cohens_kappa(pairs: list[tuple[int, int]]) -> float | None:
    """Unweighted Cohen's kappa. Returns None if undefined (fewer than 2 items)."""
    n = len(pairs)
    if n < 2:
        return None
    labels = sorted({v for pair in pairs for v in pair})
    if len(labels) == 1:
        return 1.0  # perfect, trivially: both coders used one label throughout
    observed = sum(1 for a, b in pairs if a == b) / n
    pa = {l: sum(1 for a, _ in pairs if a == l) / n for l in labels}
    pb = {l: sum(1 for _, b in pairs if b == l) / n for l in labels}
    expected = sum(pa[l] * pb[l] for l in labels)
    if expected >= 1.0:
        return 1.0
    return (observed - expected) / (1 - expected)


def reliability(codings: list[dict], maxes: dict[str, int]) -> dict[str, dict]:
    by: dict[tuple[str, str], dict[str, int]] = defaultdict(dict)
    for row in codings:
        coder = (row.get("coder") or "").strip()
        if coder in (PRIMARY_CODER, CHECK_CODER):
            try:
                by[((row["developer"] or "").strip(), (row["dimension_id"] or "").strip())][coder] = int(row["score"])
            except (ValueError, KeyError):
                continue

    out: dict[str, dict] = {}
    for did in maxes:
        pairs = [
            (v[PRIMARY_CODER], v[CHECK_CODER])
            for (dev, d), v in by.items()
            if d == did and PRIMARY_CODER in v and CHECK_CODER in v
        ]
        k = cohens_kappa(pairs)
        out[did] = {
            "n": len(pairs),
            "kappa": k,
            "agreement": (sum(1 for a, b in pairs if a == b) / len(pairs)) if pairs else None,
            "reliable": (k is not None and k >= KAPPA_FLOOR),
        }
    return out


# --------------------------------------------------------------------------- reporting


def final_scores(codings: list[dict]) -> dict[str, dict[str, int]]:
    """Reconciled coding wins; otherwise the primary coder's."""
    best: dict[str, dict[str, int]] = defaultdict(dict)
    for row in codings:
        coder = (row.get("coder") or "").strip()
        dev = (row.get("developer") or "").strip()
        did = (row.get("dimension_id") or "").strip()
        try:
            score = int(row["score"])
        except (ValueError, KeyError):
            continue
        if coder == RECONCILED or (did not in best[dev] and coder == PRIMARY_CODER):
            best[dev][did] = score
    return dict(best)


def report(codings: list[dict], maxes: dict[str, int], rel: dict[str, dict]) -> None:
    scores = final_scores(codings)
    if not scores:
        print("no final scores available yet")
        return

    devs = sorted(scores)
    unreliable = [d for d, r in rel.items() if r["n"] and not r["reliable"]]

    print(f"\nDevelopers coded: {len(devs)}")
    if unreliable:
        print(f"UNRELIABLE dimensions excluded from totals: {', '.join(sorted(unreliable))}")

    print("\nPer-dimension results")
    print(f"  {'dim':<5} {'mean':>6} {'max':>4} {'zeros':>6}  reliability")
    for did in sorted(maxes):
        vals = [scores[d][did] for d in devs if did in scores[d]]
        if not vals:
            continue
        zeros = sum(1 for v in vals if v == 0)
        r = rel.get(did, {})
        tag = (
            "n/a" if not r.get("n")
            else f"kappa {r['kappa']:.2f} (n={r['n']})" + ("" if r["reliable"] else "  << UNRELIABLE")
        )
        print(f"  {did:<5} {sum(vals)/len(vals):>6.2f} {maxes[did]:>4} {zeros:>6}  {tag}")

    print("\n'Nobody does this' — dimensions where every developer scores 0:")
    none_at_all = [
        did for did in sorted(maxes)
        if [scores[d][did] for d in devs if did in scores[d]]
        and all(scores[d].get(did, 0) == 0 for d in devs)
    ]
    print("  " + (", ".join(none_at_all) if none_at_all else "(none)"))

    d10 = [scores[d]["D10"] for d in devs if "D10" in scores[d]]
    if d10:
        print(
            f"\nHEADLINE (D10, gap to a 72-hour external reporting duty):\n"
            f"  fully compatible as written: {sum(1 for v in d10 if v == 2)}/{len(d10)}\n"
            f"  partially compatible:        {sum(1 for v in d10 if v == 1)}/{len(d10)}\n"
            f"  not compatible:              {sum(1 for v in d10 if v == 0)}/{len(d10)}"
        )

    print("\nTotals (equal weights — an arbitrary transparency choice, not an importance claim):")
    usable = [d for d in sorted(maxes) if d not in unreliable]
    denom = sum(maxes[d] for d in usable)
    for dev in sorted(devs, key=lambda d: -sum(scores[d].get(x, 0) for x in usable)):
        print(f"  {dev:<28} {sum(scores[dev].get(x, 0) for x in usable):>3} / {denom}")
    print("\nDo not lead with this table. See METHODOLOGY section 6.")


def main() -> None:
